/* Local interaction prototype. No model calls, transcription or performance grading. */
'use strict';
const $=id=>document.getElementById(id), M=BassModel, FRET_COUNT=21;
const chords={Am7:{root:'A',quality:'minor7',bass:33},Fmaj7:{root:'F',quality:'major7',bass:29},Cmaj7:{root:'C',quality:'major7',bass:36},G7:{root:'G',quality:'dominant7',bass:31}};
const sections={intro:['Am7','Am7','Fmaj7','G7'],verse:['Am7','Fmaj7','Cmaj7','G7','Am7','Fmaj7','Cmaj7','G7'],chorus:['Fmaj7','G7','Am7','Am7','Fmaj7','G7','Am7','Am7']};
const sectionNames={intro:'前奏',verse:'主歌',chorus:'副歌'};
let state={section:'verse',bar:0,stage:0,bpm:92,selected:{string:0,fret:5},focus:0,pattern:'fifths',notes:[],reviews:[],bassOn:true};
let history=[], audioCtx, playing=false, timer, tick=0,nextTime=0, sources=[], visualTimers=[], toastTimer, localURL;
let labSelected={string:0,fret:5};
const cards=[
 {title:'先找到和弦的骨架',tag:'01 / 和声',text:'Am7 的构成音是 A、C、E、G，即 1、♭3、5、♭7。先听根音与五度怎样支撑和弦，再决定是否加其他音。和弦音优先是一种入门教学策略，并不禁止经过音。',task:'试弹 A1（E 弦 5 品）→ E2（A 弦 7 品），再回到 A1。',url:'https://www.studybass.com/lessons/bass-chord-patterns/chord-tones-are-primary/',source:'StudyBass · Chord Tones Are Primary'},
 {title:'从下一拍，倒推连接音',tag:'02 / 连接',text:'半音趋近可以从目标音上方或下方进入。先确定下一和弦目标，再选邻接音，并注意出现位置、音长与解决。不是所有非和弦音都错误，也不是所有和弦音都适合长时间强调。',task:'Am7 → Fmaj7：在 4& 轻弹 E1，下一小节第一拍落 F1。E 也是 Am7 的五度。',url:'https://www.studybass.com/lessons/common-bass-patterns/chromatic-approach-notes/',source:'StudyBass · Chromatic Approach Notes'},
 {title:'休止，也是贝斯线的一部分',tag:'03 / 节奏',text:'八分与十六分细分帮助你知道音符处在拍内哪里。发音结束的位置也影响与鼓、人声的关系。原型用短/长两个门限演示音长，完整产品还需连音、切分与细分设置。',task:'音高不变，对比短音与长音，再将一个格子改为休止。',url:'https://www.studybass.com/lessons/rhythm/subdividing-the-beat/',source:'StudyBass · Subdividing the Beat'},
 {title:'低音不一定是根音',tag:'04 / 转位',text:'C/E 的和弦根音是 C，指定低音是 E。斜线右侧指出需要强调的低音；它可能是和弦音，也可能不是。先尊重编曲给出的低音要求。',task:'对比 C–C/E–F：让贝斯先走 C、E、F，听低音的方向。',url:'https://www.studybass.com/lessons/reading-music/slash-chords/',source:'StudyBass · Slash Chords'},
 {title:'同一个音，换个位置',tag:'05 / 指板',text:'标准四弦相邻空弦相差纯四度，即 5 半音。E 弦 5 品和 A 空弦同为 A1；G 弦 2 品是 A2。换位置可能改变音色和延音控制。',task:'依次弹 E5、A0、G2；辨认哪个是高八度。',url:'https://www.studybass.com/lessons/intervals/basic-intervals/',source:'StudyBass · Basic Intervals'},
 {title:'让段落决定变化',tag:'06 / 曲式',text:'先知道自己在第几小节、哪里换和弦，再决定副歌是否增加密度、音区或力度。增加音符不是唯一办法，重复和留白也能形成对比。这里的设计建议需结合具体歌曲。',task:'相同进行走两轮：第一轮只弹根音，第二轮只在最后一小节变化。',url:'https://online.berklee.edu/courses/bass-performance-101',source:'Berklee · Bass Performance 101 课程大纲'}
];
function pair(){let a=sections[state.section];return [a[state.bar],a[(state.bar+1)%a.length]];}
function activeChord(){return chords[pair()[state.focus>=8?1:0]];}
function fmtRole(r){return r.replaceAll('b','♭').replaceAll('#','♯');}
function soundName(p){return p.name.replaceAll('b','♭').replaceAll('#','♯')+M.spelledOctave(p.midi,p.name);}
function toast(t){$('toast').textContent=t;$('toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),3200);}
function snapshot(){history.push(JSON.stringify(state.notes));if(history.length>30)history.shift();}
function save(manual=false){try{localStorage.setItem('low-end-lab-v1',JSON.stringify(state));$('save-state').textContent='已保存在此浏览器';if(manual)toast('练习已保存。下次打开可以继续。');}catch{$('save-state').textContent='浏览器未允许保存';if(manual)toast('本地保存不可用，请从学习记录导出 JSON。');}}
function noteFromMidi(midi){let all=[];for(let s=0;s<4;s++)for(let f=0;f<=FRET_COUNT;f++){let p=M.position(s,f);if(p.midi===midi)all.push(p);}return all.sort((a,b)=>Math.abs(a.fret-4)-Math.abs(b.fret-4))[0];}
function makePattern(kind){snapshot();let ns=Array(16).fill(null);pair().forEach((symbol,bar)=>{let c=chords[symbol],root=noteFromMidi(c.bass),fifth=noteFromMidi(c.bass+7);for(const step of [0,4])ns[bar*8+step]={string:root.string,fret:root.fret,gate:.25};if(kind!=='roots')for(const step of [3,6])ns[bar*8+step]={string:fifth.string,fret:fifth.fret,gate:.25};if(kind==='approach'){let target=chords[pair()[bar===0?1:0]].bass;let p=noteFromMidi(target-1);if(p)ns[bar*8+7]={string:p.string,fret:p.fret,gate:.25};}});state.notes=ns;state.pattern=kind;render();save();}
function renderBars(){let a=sections[state.section];$('bars').innerHTML=a.map((c,i)=>`<button class="bar ${i===state.bar?'selected':''} ${i===(state.bar+1)%a.length?'next':''}" data-bar="${i}" aria-pressed="${i===state.bar}"><small>${String(i+1).padStart(2,'0')}</small><strong>${c}</strong></button>`).join('');$('pair-caption').textContent=`练习范围 ${String(state.bar+1).padStart(2,'0')} → ${String((state.bar+1)%a.length+1).padStart(2,'0')}${state.bar===a.length-1?'（回到段首）':''}`;$('composer-chords').textContent=pair().join(' → ');document.querySelectorAll('[data-section]').forEach(b=>b.classList.toggle('active',b.dataset.section===state.section));$('breadcrumb').textContent=`我的歌曲 / Night Pocket / ${sectionNames[state.section]}`;}
function board(target,root,quality,tuning,selected,mode){let tones=M.chord(root,quality),html='<div></div>'+Array.from({length:FRET_COUNT+1},(_,i)=>`<div class="fret-label">${i===0?'空弦':i}</div>`).join('');for(let s=3;s>=0;s--){html+=`<div class="string-label">${M.position(s,0,tuning).name}</div>`;for(let f=0;f<=FRET_COUNT;f++){let p=M.position(s,f,tuning),t=tones.find(t=>t.pc===p.pc),role=t?.role,cls=role==='1'?'root':role?.includes('3')?'third':role?.includes('5')?'fifth':role?.includes('7')?'seventh':'tone';html+=`<div class="note-cell ${s<2?'thick':''} ${f===0?'open':''}"><button class="note ${t?cls:'off'} ${selected.string===s&&selected.fret===f?'picked':''}" data-string="${s}" data-fret="${f}" aria-label="${4-s} 弦 ${f} 品 ${soundName({...p,name:t?.name||p.name})} ${t?fmtRole(role):'非和弦音'}">${t?(mode==='role'?fmtRole(role):t.name.replaceAll('b','♭').replaceAll('#','♯')):p.name.replaceAll('b','♭')}</button></div>`;}}$(target).innerHTML=html;}
function renderBoard(){let c=activeChord(),ts=M.chord(c.root,c.quality),p=M.position(state.selected.string,state.selected.fret),t=ts.find(t=>t.pc===p.pc);$('chord-title').textContent=pair()[state.focus>=8?1:0];$('chord-tones').textContent=ts.map(t=>t.name.replaceAll('b','♭').replaceAll('#','♯')).join(' · ');board('board',c.root,c.quality,[28,33,38,43],state.selected,$('note-mode').value);$('selected-note').innerHTML=`已选 <strong>${soundName({...p,name:t?.name||p.name})}</strong> · ${4-p.string} 弦 ${p.fret} 品 · ${t?fmtRole(t.role):'非当前和弦音'} · ${p.frequency.toFixed(1)} Hz`;}
function renderSequence(){$('beat-labels').innerHTML=Array.from({length:16},(_,i)=>`<span>${i%2===0?(i%8)/2+1:'&'}</span>`).join('');$('sequence').innerHTML=state.notes.map((n,i)=>{let p=n?M.position(n.string,n.fret):null;return `<button class="step ${n?'filled':''} ${state.focus===i?'focus':''}" data-step="${i}" aria-label="第 ${Math.floor(i/8)+1} 小节 第 ${(i%8)/2+1} 拍 ${p?soundName(p):'休止'}">${p?soundName(p):'—'}<small>${n?`${4-n.string}弦${n.fret}品`:'休止'}</small></button>`;}).join('');$('length-btn').textContent=`音长：${state.notes[state.focus]?.gate>.3?'长':'短'}`;$('undo-btn').disabled=!history.length;document.querySelectorAll('[data-pattern]').forEach(b=>b.classList.toggle('active',b.dataset.pattern===state.pattern));$('edit-caption').textContent=`已选第 ${Math.floor(state.focus/8)+1} 小节 · ${(state.focus%8)/2+1} 拍，点指板改音。`;}
function renderCoach(){let [a,b]=pair(),ar=chords[a].root,br=chords[b].root;const content=[['先听清，<br>和弦在哪里变。','先循环两小节。每当和弦改变，用脚标记第一拍，再试着只弹根音。','稳定的根音先让你听清和弦轮廓。等落点稳定，再增加变化。','用根音试一轮'],['不背整块指板，<br>先认两个落点。','点一个彩色音符，听它与当前和弦的关系。先认根音和五度，再比较三音与七音。','和弦音是定位线索；音高相同也可能有不同弦品位置。用耳朵和手共同记住它。','把五度加进来'],['让连接音，<br>带你回到下一拍。','先确定下一和弦第一拍，再从它下方半音试着靠近。连接音短一些，留出解决的方向。','趋近音的作用由目标、位置和时值共同决定。不要因为它不属于当前和弦就一律判错。','听一个连接方案']][state.stage];$('coach-title').innerHTML=content[0];$('coach-body').textContent=content[1];$('why-text').textContent=content[2];$('coach-action').textContent=content[3];$('coach-target').textContent=`${ar} → ${br}`;$('coach-detail').textContent=`下一小节第一拍，试着落到 ${br}。`;$('mission-label').textContent=`TODAY'S MISSION / 0${state.stage+1}`;document.querySelectorAll('[data-stage]').forEach(b=>{let a=Number(b.dataset.stage)===state.stage;b.classList.toggle('active',a);b.setAttribute('aria-selected',String(a));});}
function render(){renderBars();renderBoard();renderSequence();renderCoach();$('tempo').value=state.bpm;$('bpm-value').textContent=state.bpm;$('bass-toggle').textContent=`贝斯：${state.bassOn?'开':'关'}`;$('bass-toggle').setAttribute('aria-pressed',String(state.bassOn));renderLibrary();}
function labTuning(){return $('lab-tuning').value==='dropd'?[26,33,38,43]:[28,33,38,43];}
function renderLab(){let root=$('lab-root').value,q=$('lab-quality').value,tuning=labTuning(),p=M.position(labSelected.string,labSelected.fret,tuning),ts=M.chord(root,q),t=ts.find(t=>t.pc===p.pc);board('lab-board',root,q,tuning,labSelected,$('lab-mode').value);$('lab-selected').textContent=`${M.position(p.string,0,tuning).name} 弦 ${p.fret} 品 · ${soundName({...p,name:t?.name||p.name})}`;$('lab-detail').textContent=`实音 MIDI ${p.midi} · ${p.frequency.toFixed(2)} Hz · ${t?'当前和弦的 '+fmtRole(t.role):'不属于当前和弦构成音'}。`;$('lab-recipe').textContent=ts.map(t=>`${t.name.replaceAll('b','♭').replaceAll('#','♯')} (${fmtRole(t.role)})`).join(' · ');}
function renderLibrary(){$('session-count').innerHTML=`${state.reviews.length}<small>已记录自评</small>`;$('practice-tempo').innerHTML=`${state.bpm}<small>当前练习 BPM</small>`;let last=state.reviews.at(-1);if(last)$('last-review').textContent=`最近自评：${last.label}。下一步：${last.next}`;$('lesson-cards').innerHTML=cards.map((c,i)=>`<article class="lesson"><div class="eyebrow">${c.tag}</div><h2>${c.title}</h2><p>${c.task}</p><button data-card="${i}">打开知识卡</button></article>`).join('');}
function showView(v){stop();if(v!=='analysis')document.getElementById('an-audio')?.pause();document.querySelector('.topbar .badge').textContent=v==='analysis'?'真实音频 · 候选分析':'原创教学示例';if(v!=='songs')$('local-audio').pause();document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));for(let id of ['studio','songs','lab','library','analysis'])$(id+'-view')?.classList.toggle('hidden',id!==v);if(v==='lab')renderLab();if(v==='library')renderLibrary();$('breadcrumb').textContent=v==='studio'?`我的歌曲 / Night Pocket / ${sectionNames[state.section]}`:{songs:'我的歌曲',lab:'指板实验室',library:'学习记录',analysis:'真实音频 / 结构与拍点分析'}[v];}
function showCard(i){let c=cards[i];$('knowledge-title').textContent=c.title;$('knowledge-body').replaceChildren();for(let text of [c.text,'拿琴试试：'+c.task]){let p=document.createElement('p');p.textContent=text;$('knowledge-body').append(p);}let a=document.createElement('a');a.href=c.url;a.target='_blank';a.rel='noopener';a.textContent='来源：'+c.source;$('knowledge-body').append(a);let p=document.createElement('p');p.className='small';p.textContent='中文内容为原创教学释义；原文来源已核读。练习安排属于本产品教学设计。';$('knowledge-body').append(p);$('knowledge-dialog').showModal();}
async function context(){if(!audioCtx)audioCtx=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')await audioCtx.resume();return audioCtx;}
function tone(midi,time,duration=.2,volume=.12,type='triangle'){const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=440*2**((midi-69)/12);g.gain.setValueAtTime(0,time);g.gain.linearRampToValueAtTime(volume,time+.008);g.gain.exponentialRampToValueAtTime(.001,time+duration);o.connect(g);g.connect(audioCtx.destination);o.start(time);o.stop(time+duration+.02);sources.push(o);o.onended=()=>{o.disconnect();g.disconnect();sources=sources.filter(x=>x!==o);};}
async function audition(midi){try{await context();tone(midi,audioCtx.currentTime+.01,.32,.13);}catch{toast('浏览器暂时无法播放音频。可继续使用指板与编辑功能。');}}
function drum(time,step){if(step%4===0){const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.frequency.setValueAtTime(100,time);o.frequency.exponentialRampToValueAtTime(45,time+.12);g.gain.setValueAtTime(.16,time);g.gain.exponentialRampToValueAtTime(.001,time+.14);o.connect(g);g.connect(audioCtx.destination);o.start(time);o.stop(time+.15);sources.push(o);o.onended=()=>{o.disconnect();g.disconnect();sources=sources.filter(x=>x!==o);};}tone(94,time,.025,step%2===0?.014:.008,'square');if(step%4===2)tone(58,time,.055,.055,'sawtooth');}
function schedule(){while(playing&&nextTime<audioCtx.currentTime+.12){let step=tick%16,time=nextTime,beat=60/state.bpm,c=chords[pair()[step>=8?1:0]],n=state.notes[step];if(n&&state.bassOn)tone(M.position(n.string,n.fret).midi,time,n.gate*beat,.14);if(step%8===0)for(let t of M.chord(c.root,c.quality))tone(60+t.pc,time,Math.min(beat*3.7,2.5),.018,'sine');drum(time,step);let visual=setTimeout(()=>{if(!playing)return;document.querySelectorAll('.step').forEach((b,i)=>b.classList.toggle('head',i===step));let bar=step>=8?(state.bar+1)%sections[state.section].length:state.bar;document.querySelectorAll('[data-bar]').forEach(b=>b.classList.toggle('playing',Number(b.dataset.bar)===bar));$('play-caption').textContent=`${pair()[step>=8?1:0]} · 第 ${Math.floor(step/8)+1} 小节 · ${(step%8)/2+1} 拍`;visualTimers=visualTimers.filter(x=>x!==visual);},Math.max(0,(time-audioCtx.currentTime)*1000));visualTimers.push(visual);tick++;nextTime+=beat/2;}}
async function play(){if(playing){stop();return;}try{await context();playing=true;tick=0;nextTime=audioCtx.currentTime+.08;$('play-btn').textContent='停止';$('play-btn').setAttribute('aria-label','停止播放');schedule();timer=setInterval(schedule,25);}catch{toast('音频播放不可用。请检查浏览器音频权限。');}}
function stop(){playing=false;clearInterval(timer);visualTimers.forEach(clearTimeout);visualTimers=[];for(let s of sources){try{s.stop();}catch{}}sources=[];$('play-btn').textContent='播放';$('play-btn').setAttribute('aria-label','播放两小节循环');$('play-caption').textContent='听听你的两小节';document.querySelectorAll('.head,.playing').forEach(x=>x.classList.remove('head','playing'));}
function changePair(section,bar){stop();state.section=section;state.bar=bar;state.focus=0;makePattern(state.pattern==='custom'?'fifths':state.pattern);history=[];render();toast('已切换练习范围，并载入对应的示例贝斯线。');}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));
document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{state.stage=Number(b.dataset.stage);renderCoach();save();});
document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>changePair(b.dataset.section,0));
$('bars').onclick=e=>{let b=e.target.closest('[data-bar]');if(b)changePair(state.section,Number(b.dataset.bar));};
$('board').onclick=e=>{let b=e.target.closest('[data-string]');if(!b)return;snapshot();state.selected={string:Number(b.dataset.string),fret:Number(b.dataset.fret)};state.notes[state.focus]={...state.selected,gate:state.notes[state.focus]?.gate||.25};state.pattern='custom';audition(M.position(state.selected.string,state.selected.fret).midi);renderBoard();renderSequence();save();};
$('sequence').onclick=e=>{let b=e.target.closest('[data-step]');if(!b)return;state.focus=Number(b.dataset.step);if(state.notes[state.focus])state.selected={string:state.notes[state.focus].string,fret:state.notes[state.focus].fret};renderBoard();renderSequence();};
$('note-mode').onchange=renderBoard;
document.querySelectorAll('[data-pattern]').forEach(b=>b.onclick=()=>makePattern(b.dataset.pattern));
$('rest-btn').onclick=()=>{snapshot();state.notes[state.focus]=null;state.pattern='custom';renderSequence();save();};
$('length-btn').onclick=()=>{let n=state.notes[state.focus];if(!n){toast('先在这个格子里放一个音。');return;}snapshot();n.gate=n.gate>.3?.25:.45;renderSequence();save();};
$('clear-pattern').onclick=()=>{snapshot();state.notes=Array(16).fill(null);state.pattern='custom';renderSequence();save();};
$('undo-btn').onclick=()=>{if(history.length){state.notes=JSON.parse(history.pop());state.pattern='custom';renderSequence();save();}};
$('play-btn').onclick=play;$('save-btn').onclick=()=>save(true);
$('tempo').oninput=()=>{state.bpm=Number($('tempo').value);$('bpm-value').textContent=state.bpm;renderLibrary();save();};
$('bass-toggle').onclick=()=>{state.bassOn=!state.bassOn;render();save();};
$('coach-action').onclick=()=>{makePattern(['roots','fifths','approach'][state.stage]);if(!playing)play();};
$('explain-btn').onclick=()=>showCard(state.stage===2?1:state.stage===0?5:0);
$('review-btn').onclick=()=>{stop();$('review-dialog').showModal();};
const reviewData={structure:['会丢小节或漏掉和弦变化','先用根音连续走两轮，只关注和弦变化。',0],notes:['知道和弦，但找音不够快','把速度放慢，先找每个和弦的根音与五度。',1],fill:['加花后回不稳第一拍','先删除连接音，只练下一和弦第一拍，再逐个加回。',2],ready:['两轮稳定，想减少提示','将贝斯示范关闭，跟伴奏弹两轮；再尝试另一段。',2]};
document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{let [label,next,stage]=reviewData[b.dataset.review];state.reviews.push({at:new Date().toISOString(),label,next,kind:'self_report'});state.stage=stage;save();render();$('review-dialog').close();toast('已记录。'+next);});
$('lesson-cards').onclick=e=>{let b=e.target.closest('[data-card]');if(b)showCard(Number(b.dataset.card));};
for(let id of ['lab-root','lab-quality','lab-tuning','lab-mode'])$(id).onchange=renderLab;
$('lab-board').onclick=e=>{let b=e.target.closest('[data-string]');if(!b)return;labSelected={string:Number(b.dataset.string),fret:Number(b.dataset.fret)};renderLab();audition(M.position(labSelected.string,labSelected.fret,labTuning()).midi);};
$('lab-set-root').onclick=()=>{let name=M.position(labSelected.string,labSelected.fret,labTuning()).name;if(![...$('lab-root').options].some(o=>o.value===name))$('lab-root').add(new Option(name,name));$('lab-root').value=name;renderLab();};
$('open-song').onclick=()=>showView('studio');$('import-btn').onclick=()=>$('audio-file').click();
$('audio-file').onchange=()=>{let file=$('audio-file').files[0];if(!file)return;stop();if(localURL)URL.revokeObjectURL(localURL);localURL=URL.createObjectURL(file);$('local-audio').src=localURL;$('audio-name').textContent=file.name+' · 仅本地试听，未分析';$('audio-area').classList.remove('hidden');};
$('local-audio').onerror=()=>toast('此音频格式无法解码，请尝试 MP3 或 WAV。');
$('export-btn').onclick=()=>{let blob=new Blob([JSON.stringify({schemaVersion:1,type:'learning-prototype',...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='low-end-lab-practice.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
window.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','SELECT','TEXTAREA','BUTTON','A'].includes(e.target.tagName)&&!document.querySelector('dialog[open]')&&!$('studio-view').classList.contains('hidden')){e.preventDefault();play();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
function validSaved(s){return s&&sections[s.section]&&Number.isInteger(s.bar)&&s.bar>=0&&s.bar<sections[s.section].length&&[0,1,2].includes(s.stage)&&Number.isFinite(s.bpm)&&s.bpm>=50&&s.bpm<=140&&Number.isInteger(s.focus)&&s.focus>=0&&s.focus<16&&Array.isArray(s.notes)&&s.notes.length===16&&s.notes.every(n=>n===null||(Number.isInteger(n.string)&&n.string>=0&&n.string<4&&Number.isInteger(n.fret)&&n.fret>=0&&n.fret<=FRET_COUNT&&[.25,.45].includes(n.gate)))&&Array.isArray(s.reviews)&&s.reviews.every(r=>typeof r.label==='string'&&typeof r.next==='string')&&s.selected&&Number.isInteger(s.selected.string)&&s.selected.string>=0&&s.selected.string<4&&Number.isInteger(s.selected.fret)&&s.selected.fret>=0&&s.selected.fret<=FRET_COUNT;}
try{let saved=JSON.parse(localStorage.getItem('low-end-lab-v1'));if(validSaved(saved))state={...state,...saved};}catch{}
if(!state.notes.length)makePattern('fifths');history=[];render();renderLab();

// Keep the full instrument available without shrinking the note targets.
document.querySelectorAll('[data-fret-jump]').forEach(button=>button.onclick=()=>{
  const wrap=$(button.dataset.board).parentElement;
  wrap.scrollTo({left:button.dataset.fretJump==='high'?wrap.scrollWidth:0,behavior:'smooth'});
});
